declare(strict_types=1); $config=require __DIR__.'/../config/config.php'; ini_set('display_errors','0'); ini_set('log_errors','1'); ini_set('error_log',__DIR__.'/../logs/php-error.log'); session_name($config['app']['session_name']); session_set_cookie_params(['lifetime'=>2592000,'path'=>'/','secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'httponly'=>true,'samesite'=>'Lax']); session_start(); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store');
function db():PDO{static $p=null;global $config;if($p)return $p;$u=trim((string)$config['db']['url']);if($u){$x=parse_url($u);$h=$x['host'];$port=$x['port']??5432;$n=ltrim($x['path'],'/');$user=rawurldecode($x['user']??'');$pass=rawurldecode($x['pass']??'');$q=[];if(!empty($x['query']))parse_str($x['query'],$q);$ssl=$q['sslmode']??$config['db']['sslmode'];}else{$h=$config['db']['host'];$port=$config['db']['port'];$n=$config['db']['name'];$user=$config['db']['user'];$pass=$config['db']['pass'];$ssl=$config['db']['sslmode'];}$p=new PDO("pgsql:host=$h;port=$port;dbname=$n;sslmode=$ssl",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$sql=file_get_contents(__DIR__.'/../database/schema.sql');if($sql!==false)$p->exec($sql);return $p;}
function body():array{$r=file_get_contents('php://input');$d=$r?json_decode($r,true):$_POST;return is_array($d)?$d:[];} function ok(array $d=[],int $s=200):never{http_response_code($s);echo json_encode(['ok'=>true]+$d,JSON_UNESCAPED_UNICODE);exit;} function fail(string $m,int $s=400):never{http_response_code($s);echo json_encode(['ok'=>false,'error'=>$m],JSON_UNESCAPED_UNICODE);exit;}
function me():?array{if(empty($_SESSION['user_id']))return null;$s=db()->prepare('SELECT u.id,u.username,u.email,u.role,u.status,w.balance FROM users u JOIN wallets w ON w.user_id=u.id WHERE u.id=?');$s->execute([(int)$_SESSION['user_id']]);return $s->fetch()?:null;} function user():array{$u=me();if(!$u)fail('Chưa đăng nhập',401);if($u['status']!=='active')fail('Tài khoản đã bị khóa',403);return $u;} function admin():array{$u=user();if($u['role']!=='admin')fail('Không có quyền quản trị',403);return $u;}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];} function checkcsrf():void{if($_SERVER['REQUEST_METHOD']==='GET')return;$t=$_SERVER['HTTP_X_CSRF_TOKEN']??(body()['_csrf']??'');if(!hash_equals(csrf(),(string)$t))fail('CSRF token không hợp lệ',419);}
function audit(int $actor,string $action,?int $target,array $payload=[]):void{$s=db()->prepare("INSERT INTO audit_logs(actor_user_id,action,target_user_id,ip_address,user_agent,payload_json) VALUES(?,?,?,?,?,?::jsonb)");$s->execute([$actor,$action,$target,$_SERVER['REMOTE_ADDR']??null,substr($_SERVER['HTTP_USER_AGENT']??'',0,500),json_encode($payload,JSON_UNESCAPED_UNICODE)]);}
